create temp table roster_qa_import_graph on commit drop as
  with recursive graph(id) as (
    select id from collect_hybrid.roster_import_sources where actor_id='99880000-0000-4000-8000-000000000001' and request_id::text like '99880000-%'
    union select t.to_import_id from collect_hybrid.roster_recovery_transfers t join graph g on g.id=t.from_import_id
      where t.actor_id='99880000-0000-4000-8000-000000000001'
  ) select distinct id from graph;
create temp table roster_qa_group_graph on commit drop as
  select distinct c.collection_id id from collect_hybrid.roster_import_commits c join roster_qa_import_graph g on g.id=c.import_id
  where c.actor_id='99880000-0000-4000-8000-000000000001' and c.request_id::text like '99880000-%' and c.response->>'mode'='create';
create temp table roster_qa_member_graph on commit drop as
  select distinct member_record_id id from public.collection_members where collection_id in (select id from roster_qa_group_graph) and member_record_id is not null
  union select id from collect_hybrid.member_records where id in ('99880000-0000-4000-8000-000000000001','99880000-0000-4000-8000-000000000002');
create temp table roster_qa_resource_graph on commit drop as
  select r.id from collect_hybrid.roster_resource_reservations r join collect_hybrid.roster_import_sources s on s.request_id=r.request_id
    join roster_qa_import_graph g on g.id=s.id where r.actor_id='99880000-0000-4000-8000-000000000001' and r.request_id::text like '99880000-%'
  union select id from collect_hybrid.roster_resource_reservations where actor_id='99880000-0000-4000-8000-000000000001' and request_id::text like '99880000-%';
do $$ declare relation_name text; outlier boolean; begin
  if exists(select 1 from collect_hybrid.roster_import_sources where actor_id='99880000-0000-4000-8000-000000000001' and id not in (select id from roster_qa_import_graph))
   or exists(select 1 from collect_hybrid.roster_recovery_transfers where actor_id='99880000-0000-4000-8000-000000000001' and
      (request_id::text not like '99880000-%' or from_import_id not in (select id from roster_qa_import_graph) or to_import_id not in (select id from roster_qa_import_graph) or root_import_id not in (select id from roster_qa_import_graph)))
   or exists(select 1 from collect_hybrid.roster_resource_reservations where actor_id='99880000-0000-4000-8000-000000000001' and id not in (select id from roster_qa_resource_graph))
   or exists(select 1 from public.collections where creator_user_id='99880000-0000-4000-8000-000000000001' and id not in (select id from roster_qa_group_graph))
   or exists(select 1 from collect_hybrid.group_creation_requests where actor_id='99880000-0000-4000-8000-000000000001' and collection_id not in (select id from roster_qa_group_graph))
   or exists(select 1 from collect_hybrid.roster_batches where actor_id='99880000-0000-4000-8000-000000000001' and collection_id not in (select id from roster_qa_group_graph))
   or exists(select 1 from collect_hybrid.member_records where created_by='99880000-0000-4000-8000-000000000001' and id not in (select id from roster_qa_member_graph)) then
    raise exception 'Unattributed synthetic graph; cleanup denied'; end if;
  foreach relation_name in array array['roster_import_extractions','roster_import_revisions','roster_import_results','roster_import_commits','roster_import_recovery_intents','roster_import_editor_drafts'] loop
    execute format('select exists(select 1 from collect_hybrid.%I where actor_id=$1 and import_id not in (select id from roster_qa_import_graph))',relation_name) into strict outlier using '99880000-0000-4000-8000-000000000001'::uuid;
    if outlier then raise exception 'Unattributed owned provenance rows; cleanup denied'; end if;
  end loop;
end $$;

